void status_req_fuel_level(void * arg)
{
  	UInt8 data[2]  = {SET_FUEL_LEVEL, 0xFF};

#if STATUS_ENGINE_ENABLE == 1
  	
   		data[1] = status_get_engine (STATUS_ENG_FUEL_LEVEL) ;
    
#endif

  	d2d_tx_frame (&data[0] , sizeof_array(data)) ;  
}

